create extension if not exists pgcrypto;
create table if not exists users(id uuid primary key default gen_random_uuid(),email text not null unique,username text not null unique check(username ~ '^[A-Za-z0-9_.-]{3,24}$'),password_hash text not null,avatar_url text,bio text check(char_length(bio)<=300),is_seller boolean not null default false,role text not null default 'user' check(role in('user','admin')),created_at timestamptz not null default now());
create table if not exists games(id uuid primary key default gen_random_uuid(),slug text not null unique,name text not null,platform text,is_active boolean not null default true);
create table if not exists categories(id uuid primary key default gen_random_uuid(),slug text not null unique,name text not null);
create table if not exists game_categories(game_id uuid references games on delete cascade,category_id uuid references categories on delete cascade,primary key(game_id,category_id));
create table if not exists listings(id uuid primary key default gen_random_uuid(),seller_id uuid not null references users on delete cascade,game_id uuid not null references games,category_id uuid not null references categories,title text not null check(char_length(title) between 5 and 120),summary text check(char_length(summary)<=300),details text check(char_length(details)<=3000),price_cents integer not null check(price_cents>0),currency text not null default 'RUB',stock integer not null default 1 check(stock>=0),delivery_time text,status text not null default 'pending' check(status in('pending','active','rejected','archived')),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists orders(id uuid primary key default gen_random_uuid(),listing_id uuid not null references listings,buyer_id uuid not null references users,seller_id uuid not null references users,unit_price_cents integer not null check(unit_price_cents>0),quantity integer not null check(quantity>0),total_cents integer not null check(total_cents>0),currency text not null,status text not null default 'pending_payment' check(status in('pending_payment','paid','in_progress','completed','cancelled','dispute')),payment_status text not null default 'not_configured' check(payment_status in('not_configured','pending','confirmed','failed','refunded')),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists order_events(id bigint generated always as identity primary key,order_id uuid not null references orders on delete cascade,status text not null,actor_id uuid,created_at timestamptz not null default now());
create table if not exists payments(id uuid primary key default gen_random_uuid(),order_id uuid not null references orders,provider text not null,provider_payment_id text not null,amount_cents integer not null,status text not null,raw_event jsonb,created_at timestamptz not null default now(),unique(provider,provider_payment_id));
create table if not exists conversations(id uuid primary key default gen_random_uuid(),listing_id uuid references listings on delete set null,buyer_id uuid not null references users,seller_id uuid not null references users,created_at timestamptz not null default now(),unique(listing_id,buyer_id));
create table if not exists messages(id uuid primary key default gen_random_uuid(),conversation_id uuid not null references conversations on delete cascade,sender_id uuid not null references users,body text not null check(char_length(body) between 1 and 2000),created_at timestamptz not null default now(),read_at timestamptz);
create table if not exists reviews(id uuid primary key default gen_random_uuid(),order_id uuid not null unique references orders,reviewer_id uuid not null references users,seller_id uuid not null references users,rating integer not null check(rating between 1 and 5),body text check(char_length(body)<=1000),created_at timestamptz not null default now());
create table if not exists favorites(user_id uuid references users on delete cascade,listing_id uuid references listings on delete cascade,created_at timestamptz not null default now(),primary key(user_id,listing_id));
create table if not exists disputes(id uuid primary key default gen_random_uuid(),order_id uuid not null references orders,opened_by uuid not null references users,reason text not null check(char_length(reason) between 10 and 2000),status text not null default 'open' check(status in('open','resolved_buyer','resolved_seller','closed')),resolution text,resolved_by uuid references users,created_at timestamptz not null default now());
create table if not exists reports(id uuid primary key default gen_random_uuid(),reporter_id uuid not null references users,target_type text not null check(target_type in('listing','user','message')),target_id uuid not null,reason text not null check(char_length(reason) between 5 and 1000),status text not null default 'open' check(status in('open','closed')),created_at timestamptz not null default now());
create index if not exists i_l1 on listings(game_id,category_id,status);
create index if not exists i_l2 on listings(seller_id);
create index if not exists i_o1 on orders(buyer_id);
create index if not exists i_o2 on orders(seller_id);
create index if not exists i_m1 on messages(conversation_id,created_at);
create index if not exists i_r1 on reviews(seller_id);
insert into categories(slug,name) values('currency','Игровая валюта'),('items','Игровые предметы'),('skins','Скины'),('accounts','Игровые аккаунты'),('keys','Ключи активации'),('gifts','Подарки и цифровые товары'),('topup','Пополнение баланса'),('subscriptions','Подписки'),('boost','Прокачка'),('services','Игровые услуги'),('other','Прочее') on conflict do nothing;
